CREATE TABLE IF NOT EXISTS users(
 id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash TEXT NOT NULL,
 role VARCHAR(20) NOT NULL DEFAULT 'VIEWER' CHECK(role IN('ADMIN','MANAGER','CASHIER','STOCK','VIEWER')),active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers(id BIGSERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,document VARCHAR(20),phone VARCHAR(30),email VARCHAR(180),credit_limit NUMERIC(14,2) NOT NULL DEFAULT 0,address TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS suppliers(id BIGSERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,document VARCHAR(20),phone VARCHAR(30),email VARCHAR(180),address TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS warehouses(id BIGSERIAL PRIMARY KEY,name VARCHAR(100) NOT NULL,code VARCHAR(30) UNIQUE NOT NULL,address TEXT,active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS products(
 id BIGSERIAL PRIMARY KEY,sku VARCHAR(60) UNIQUE NOT NULL,barcode VARCHAR(80),name VARCHAR(180) NOT NULL,category VARCHAR(100),brand VARCHAR(100),unit VARCHAR(10) NOT NULL DEFAULT 'UN',
 ncm VARCHAR(10),cest VARCHAR(10),cost NUMERIC(14,4) NOT NULL DEFAULT 0,price NUMERIC(14,4) NOT NULL DEFAULT 0,min_stock NUMERIC(14,3) NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS stock_balances(product_id BIGINT REFERENCES products(id),warehouse_id BIGINT REFERENCES warehouses(id),quantity NUMERIC(14,3) NOT NULL DEFAULT 0,PRIMARY KEY(product_id,warehouse_id));
CREATE TABLE IF NOT EXISTS stock_movements(id BIGSERIAL PRIMARY KEY,product_id BIGINT REFERENCES products(id),warehouse_id BIGINT REFERENCES warehouses(id),movement_type VARCHAR(20) NOT NULL,quantity NUMERIC(14,3) NOT NULL,unit_cost NUMERIC(14,4),reference_type VARCHAR(30),reference_id BIGINT,notes TEXT,user_id BIGINT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS purchases(id BIGSERIAL PRIMARY KEY,supplier_id BIGINT REFERENCES suppliers(id),warehouse_id BIGINT REFERENCES warehouses(id),status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',invoice_number VARCHAR(60),total NUMERIC(14,2) NOT NULL DEFAULT 0,user_id BIGINT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now(),received_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS purchase_items(id BIGSERIAL PRIMARY KEY,purchase_id BIGINT REFERENCES purchases(id) ON DELETE CASCADE,product_id BIGINT REFERENCES products(id),quantity NUMERIC(14,3) NOT NULL,unit_cost NUMERIC(14,4) NOT NULL,subtotal NUMERIC(14,2) NOT NULL);
CREATE TABLE IF NOT EXISTS sales(id BIGSERIAL PRIMARY KEY,customer_id BIGINT REFERENCES customers(id),status VARCHAR(20) NOT NULL DEFAULT 'COMPLETED',payment_method VARCHAR(30) NOT NULL DEFAULT 'CASH',subtotal NUMERIC(14,2) NOT NULL DEFAULT 0,discount NUMERIC(14,2) NOT NULL DEFAULT 0,total NUMERIC(14,2) NOT NULL DEFAULT 0,user_id BIGINT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS sale_items(id BIGSERIAL PRIMARY KEY,sale_id BIGINT REFERENCES sales(id) ON DELETE CASCADE,product_id BIGINT REFERENCES products(id),warehouse_id BIGINT REFERENCES warehouses(id),quantity NUMERIC(14,3) NOT NULL,unit_price NUMERIC(14,4) NOT NULL,subtotal NUMERIC(14,2) NOT NULL);
CREATE TABLE IF NOT EXISTS receivables(id BIGSERIAL PRIMARY KEY,customer_id BIGINT REFERENCES customers(id),sale_id BIGINT REFERENCES sales(id),description VARCHAR(180) NOT NULL,amount NUMERIC(14,2) NOT NULL,due_date DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',paid_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS payables(id BIGSERIAL PRIMARY KEY,supplier_id BIGINT REFERENCES suppliers(id),purchase_id BIGINT REFERENCES purchases(id),description VARCHAR(180) NOT NULL,amount NUMERIC(14,2) NOT NULL,due_date DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',paid_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS deliveries(id BIGSERIAL PRIMARY KEY,sale_id BIGINT REFERENCES sales(id),customer_id BIGINT REFERENCES customers(id),address TEXT NOT NULL,scheduled_date DATE,driver VARCHAR(120),vehicle VARCHAR(80),freight NUMERIC(14,2) NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',notes TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),action VARCHAR(80) NOT NULL,entity VARCHAR(80) NOT NULL,entity_id VARCHAR(80),details JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_products_name ON products(name);CREATE INDEX IF NOT EXISTS idx_stock_product ON stock_movements(product_id);CREATE INDEX IF NOT EXISTS idx_sales_date ON sales(created_at);CREATE INDEX IF NOT EXISTS idx_audit_date ON audit_logs(created_at);
